import{_ as e,o as t,c as r,a3 as n}from"./chunks/framework.B5WAEDB7.js";const u=JSON.parse('{"title":"生态总览","description":"","frontmatter":{"title":"生态总览","index":false},"headers":[],"relativePath":"cosmos/ecosystem.md","filePath":"cosmos/ecosystem.md","lastUpdated":1787829917000}'),s={name:"cosmos/ecosystem.md"};function o(i,a,p,d,h,c){return t(),r("div",null,[...a[0]||(a[0]=[n(`<h1 id="生态总览" tabindex="-1">生态总览 <a class="header-anchor" href="#生态总览" aria-label="Permalink to &quot;生态总览&quot;">​</a></h1><p>曦寒不是一个仓库，而是三个可以独立使用、也可以叠起来用的开源项目。本页讲它们各自是什么、彼此什么关系、你的场景该从哪个进去。</p><p>三者各有独立的文档站，本站只负责生态层面的导览与共同的贡献约定。</p><h2 id="三个仓库" tabindex="-1">三个仓库 <a class="header-anchor" href="#三个仓库" aria-label="Permalink to &quot;三个仓库&quot;">​</a></h2><table tabindex="0"><thead><tr><th>定位</th><th>项目</th><th>技术栈</th><th>文档站</th></tr></thead><tbody><tr><td>后端基座</td><td><a href="https://github.com/XiHanFun/XiHan.Framework" target="_blank" rel="noreferrer">XiHan.Framework</a></td><td>.NET 10</td><td><a href="https://framework.docs.xihanfun.com/" target="_blank" rel="noreferrer">framework.docs.xihanfun.com</a></td></tr><tr><td>组件层</td><td><a href="https://github.com/XiHanFun/XiHan.UI" target="_blank" rel="noreferrer">XiHan.UI</a></td><td>TypeScript · Vue 3 · Web Components</td><td><a href="https://ui.docs.xihanfun.com/" target="_blank" rel="noreferrer">ui.docs.xihanfun.com</a></td></tr><tr><td>基础应用</td><td><a href="https://github.com/XiHanFun/XiHan.BasicApp" target="_blank" rel="noreferrer">XiHan.BasicApp</a></td><td>.NET 10 + Vue 3</td><td><a href="https://basicapp.docs.xihanfun.com/" target="_blank" rel="noreferrer">basicapp.docs.xihanfun.com</a></td></tr></tbody></table><h3 id="xihan-framework-·-后端基座" tabindex="-1">XiHan.Framework · 后端基座 <a class="header-anchor" href="#xihan-framework-·-后端基座" aria-label="Permalink to &quot;XiHan.Framework · 后端基座&quot;">​</a></h3><p>快速、轻量、高效、用心的 .NET 现代模块化开发框架。是面向企业级应用的模块化后端框架，框架优先使用 .NET 原生功能，减少第三方依赖，理念现代、开箱即用、模块清晰、依赖可控、扩展可维护。属于曦寒懿（XiHanFun）开源生态的后端基座，拥有底座、组件、应用的完整生态。</p><p>按需引用的 NuGet 包，模块之间用 <code>[DependsOn]</code> 声明依赖，启动时自动拓扑排序装配。</p><h3 id="xihan-ui-·-组件层" tabindex="-1">XiHan.UI · 组件层 <a class="header-anchor" href="#xihan-ui-·-组件层" aria-label="Permalink to &quot;XiHan.UI · 组件层&quot;">​</a></h3><p>快速、轻量、高效、用心的框架无关跨端组件库。是面向企业级前端的设计系统运行时，无头内核，Vue 3 与 Web Components 适配器。提供基础组件与 AI 组件，覆盖从中后台到 AI 对话的界面构建场景。属于曦寒懿（XiHanFun）开源生态的组件层，拥有底座、组件、应用的完整生态。</p><h3 id="xihan-basicapp-·-基础应用" tabindex="-1">XiHan.BasicApp · 基础应用 <a class="header-anchor" href="#xihan-basicapp-·-基础应用" aria-label="Permalink to &quot;XiHan.BasicApp · 基础应用&quot;">​</a></h3><p>基于 .Net + Vue 的超高颜值中后台内核。开箱即用，提供 RBAC + ABAC 混合权限管理、多租户隔离、代码生成、实时通信、灰度发布、AI 等核心能力，满足新型企业级中后台管理场景。属于曦寒懿（XiHanFun）开源生态的基础应用，拥有底座、组件、应用的完整生态。</p><h2 id="彼此什么关系" tabindex="-1">彼此什么关系 <a class="header-anchor" href="#彼此什么关系" aria-label="Permalink to &quot;彼此什么关系&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>      ┌───────────────────────────────┐</span></span>
<span class="line"><span>      │        XiHan.BasicApp         │  企业级中后台，可直接投产</span></span>
<span class="line"><span>      │  后端 modules/  ·  前端 src/  │</span></span>
<span class="line"><span>      └───────┬───────────────┬───────┘</span></span>
<span class="line"><span>              │ 引用 NuGet    │ 引用 npm 包</span></span>
<span class="line"><span>      ┌───────▼───────┐  ┌────▼─────────────┐</span></span>
<span class="line"><span>      │ XiHan.Framework│  │   XiHan.UI      │</span></span>
<span class="line"><span>      │  .NET 模块包   │  │  设计系统运行时  │</span></span>
<span class="line"><span>      └───────────────┘  └─────────────────┘</span></span></code></pre></div><p>两条依赖关系值得先说清楚：</p><ul><li><strong>BasicApp 的后端确实建立在 Framework 之上</strong>：它引用框架的 NuGet 包，认证、授权、数据访问、多租户、动态 API 等底层能力都来自框架，BasicApp 只写业务。想看框架能力在真实业务里怎么落地，读 BasicApp 的源码是最快的路径。</li><li><strong>BasicApp 的前端同样建立在 UI 之上</strong>：自 BasicApp v4.0.0 起，前端整体用 XiHan.UI 重建，naive-ui 全量下线。想看组件库在真实业务里怎么用，读 BasicApp 前端的源码是最快的路径。</li></ul><p>Framework 与 UI 之间没有依赖关系，一个是 .NET 后端包，一个是前端库，各自可以单独使用。</p><h2 id="我该从哪个进去" tabindex="-1">我该从哪个进去 <a class="header-anchor" href="#我该从哪个进去" aria-label="Permalink to &quot;我该从哪个进去&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你的场景</th><th>从这里开始</th></tr></thead><tbody><tr><td>要在自己的 .NET 项目里用模块化框架、只取其中几个能力</td><td><a href="https://framework.docs.xihanfun.com/quickstart" target="_blank" rel="noreferrer">开发框架 · 快速上手</a></td></tr><tr><td>要一套现成的中后台系统，改改就能上线</td><td><a href="https://basicapp.docs.xihanfun.com/getting-started" target="_blank" rel="noreferrer">基础应用 · 快速开始</a></td></tr><tr><td>要在自己的前端项目里用组件库，或做跨框架的设计系统</td><td><a href="https://ui.docs.xihanfun.com/overview" target="_blank" rel="noreferrer">视图组件 · 架构总览</a></td></tr><tr><td>还在选型，想先看清楚适合不适合</td><td><a href="https://framework.docs.xihanfun.com/why" target="_blank" rel="noreferrer">为什么选择曦寒框架</a> · <a href="https://basicapp.docs.xihanfun.com/why" target="_blank" rel="noreferrer">为什么选择曦寒基础应用</a></td></tr><tr><td>想先跑起来看看长什么样</td><td><a href="https://basicapp.xihanfun.com" target="_blank" rel="noreferrer">在线预览</a></td></tr></tbody></table><h2 id="版本与发布" tabindex="-1">版本与发布 <a class="header-anchor" href="#版本与发布" aria-label="Permalink to &quot;版本与发布&quot;">​</a></h2><p>三个仓库<strong>独立发版</strong>，版本号互不对齐：</p><ul><li>Framework 发布到 <a href="https://www.nuget.org/profiles/XiHanFun" target="_blank" rel="noreferrer">NuGet</a>，版本真源是 <code>framework/props/version.props</code></li><li>BasicApp 随仓库发布，版本真源是 <code>backend/props/version.props</code></li><li>UI 发布到 <a href="https://www.npmjs.com/org/xihan-ui" target="_blank" rel="noreferrer">npm</a>，17 个公开包由 changesets 的 <code>fixed</code> 组锁步同版，版本真源是 <code>ui/packages/*/*/package.json</code></li></ul><p>各站导航栏右上角的徽章显示的就是该项目当前的版本与发布阶段。</p><h2 id="参与进来" tabindex="-1">参与进来 <a class="header-anchor" href="#参与进来" aria-label="Permalink to &quot;参与进来&quot;">​</a></h2><p>三个仓库在 GitHub（主库）、Gitee 与 GitCode（同步备库）上都可访问，Issue 与 PR 三个平台都收。共同的约定见<a href="./contributing">参与贡献指南</a>与<a href="./code-of-conduct">行为公约</a>。</p>`,25)])])}const f=e(s,[["render",o]]);export{u as __pageData,f as default};
